def generate_checker_texture(width=8, height=8):
    """生成線性 RGB 的 Checkerboard 貼圖，用於測試。"""
    tex = np.zeros((height, width, 3), dtype=np.float32)
    for y in range(height):
        for x in range(width):
            if (x + y) % 2 == 0:
                tex[y, x] = [1.0, 1.0, 1.0]
            else:
                tex[y, x] = [0.0, 0.0, 0.0]
    return tex

